const GRIP_TOUCH_TARGET: Record<WorkspaceLayout, string> = {
  full: '',
  compact: 'flex h-full min-w-7 items-center justify-center',
}

function trackIcon(track: Track) {
  const first = track.elements[0]?.type
  if (!first) return LayersIcon
  return getElementUI(first).icon
}

function keepsTranscriptTimingSoNeverCompacts(track: Track): boolean {
  return track.elements.length > 0 && track.elements.every((e) => e.type === 'caption')
}

function TrackHeader({ track, gripProps }: { track: Track; gripProps?: Record<string, unknown> }) {
  const engine = useEditor()
  const { layout, timelineHeaderPx } = useEditorUI()
  const [renaming, setRenaming] = useState(false)

  return (
    <ContextMenu>
      <ContextMenuTrigger
        render={
          <div
            className="group/header sticky left-0 z-50 flex shrink-0 items-center gap-1 border-r border-foreground/10 bg-card pr-2 pl-0.5"
            style={{ width: timelineHeaderPx, height: TRACK_HEIGHT }}
            onClick={(event) => {
              if ((event.target as HTMLElement).closest('button, input')) return
              selectTrackElements(engine, track.id)
            }}
          />
        }
      >
        <button
          type="button"
          className={cn('cursor-grab touch-none text-muted-foreground/50 hover:text-muted-foreground', GRIP_TOUCH_TARGET[layout])}
          aria-label="Reorder track"
          {...gripProps}
        >
          <GripVerticalIcon className="size-3.5" />
        </button>
        {createElement(trackIcon(track), {
          className: 'size-3.5 shrink-0 text-muted-foreground',
        })}
        {renaming ? (
          <Input
            autoFocus
            defaultValue={track.name}
            className="h-5 flex-1 px-1 text-2xs"
            onBlur={(e) => {
              const name = e.target.value.trim()
              if (name && name !== track.name) {
                engine.dispatch({ type: 'renameTrack', trackId: track.id, name })
              }
              setRenaming(false)
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter') (e.target as HTMLInputElement).blur()
              if (e.key === 'Escape') setRenaming(false)
            }}
          />
        ) : (
          <span className="min-w-6 flex-1 truncate text-2xs font-medium" onDoubleClick={() => setRenaming(true)}>
            {track.name}
          </span>
        )}
        <TrackFlags track={track} layout={layout} />
      </ContextMenuTrigger>
      <ContextMenuContent>
        <ContextMenuItem onClick={() => selectTrackElements(engine, track.id)}>Select clips</ContextMenuItem>
        <ContextMenuItem onClick={() => setRenaming(true)}>Rename</ContextMenuItem>
        <ContextMenuItem
          onClick={() => {
            const index = engine.project.tracks.findIndex((t) => t.id === track.id)
            engine.dispatch({ type: 'addTrack', index: index + 1 })
          }}
        >
          Insert track above
        </ContextMenuItem>
        <ContextMenuItem
          onClick={() => {
            const index = engine.project.tracks.findIndex((t) => t.id === track.id)
            engine.dispatch({ type: 'addTrack', index })
          }}
        >
          Insert track below
        </ContextMenuItem>
        <ContextMenuSeparator />
        <ContextMenuItem variant="destructive" onClick={() => engine.dispatch({ type: 'removeTrack', trackId: track.id })}>
          Delete track
        </ContextMenuItem>
      </ContextMenuContent>
    </ContextMenu>
  )
}

